test('NATIVE-TITLE-UI: provisional candidates remain visible but only the committed title is journaled',async({page})=>{
 const f=await fixture(page,true);await page.goto('/native-auth.fixture.html');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();const title=page.getByRole('textbox',{name:'Pageタイトル',exact:true});await title.focus();await title.dispatchEvent('compositionstart');for(const candidate of ['に','日本','日本語'])await title.fill(candidate);await expect(title).toHaveValue('日本語');expect(f.calls.filter(c=>(c.args?.request as {command?:string})?.command==='title_enqueue')).toHaveLength(0);await title.dispatchEvent('compositionend');await expect.poll(()=>f.calls.filter(c=>(c.args?.request as {command?:string})?.command==='title_enqueue').length).toBe(1);await expect(title).toBeFocused();
});
