 f.titleConflicts.push({record:{id:cfId,operationId:'01900000-0000-7000-8000-000000000009',baseVersion:0,remoteVersion:1,base:'before',local:'retained local candidate',remote:'server candidate'},resolvedBy:null});
 await page.goto('/native-auth.fixture.html');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();
