async function readFixture(page:Page){const f=await fixture(page,true);await page.goto('/native-auth.fixture.html');await expect(state(page)).toHaveText('認証を確認しました');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();const editor=page.getByRole('textbox',{name:'Page本文',exact:true});await editor.fill('alpha beta');await expect.poll(()=>f.body(id)).toContain('alpha beta');return{f,editor};}
test('NATIVE-PAGE-READ-UI: remote prefix keeps text selection/focus and local Undo excludes remote edits',async({page},testInfo)=>{
 const {f,editor}=await readFixture(page);f.remotePrefix('REMOTE ');f.holdRead();await page.getByRole('button',{name:'このPageの変更を取得',exact:true}).click();await f.waitReading();await editor.focus();await expect(editor).toBeFocused();await page.keyboard.press('Control+End');await expect.poll(async()=>(await diagnostic(page)).selection).toMatchObject({from:11,to:11});for(let index=0;index<4;index++)await page.keyboard.press('Shift+ArrowLeft');const before=await diagnostic(page);const selected=await page.evaluate(()=>document.getSelection()?.toString());expect(selected).toContain('beta');const writes=f.calls.filter(c=>(c.args?.request as {command?:string}|undefined)?.command==='page_append').length;f.releaseRead();await expect(page.getByLabel('Pageの取得状態')).toHaveText('取得内容を端末に保存し、本文へ反映しました。');await expect(editor).toContainText('REMOTE alpha beta');await expect(editor).toBeFocused();expect(await page.evaluate(()=>document.getSelection()?.toString())).toBe(selected);expect((await diagnostic(page)).selection.from).toBe(before.selection.from+7);expect(f.calls.filter(c=>(c.args?.request as {command?:string}|undefined)?.command==='page_append')).toHaveLength(writes);
 await page.keyboard.press('End');await page.keyboard.type(' local edit');await expect.poll(()=>f.body(id)).toContain('local edit');await page.keyboard.press('Control+z');await expect(editor).toContainText('REMOTE alpha beta');await expect(editor).not.toContainText('local edit');expect(f.networkReads).toBe(1);await page.screenshot({path:testInfo.outputPath('native-read.png'),fullPage:true});
});
test('NATIVE-PAGE-READ-UI: response during composition is durable but view waits for confirmation without cancelling focus',async({page})=>{
 const {f,editor}=await readFixture(page);f.remotePrefix('REMOTE ');f.holdRead();await page.getByRole('button',{name:'このPageの変更を取得',exact:true}).click();await f.waitReading();await editor.focus();await editor.dispatchEvent('compositionstart',{data:'確定'});await expect(page.getByRole('button',{name:'このPageの変更を取得',exact:true})).toBeDisabled();f.releaseRead();await expect(page.getByLabel('Pageの取得状態')).toContainText('変換の確定後');await expect(editor).not.toContainText('REMOTE');await expect(editor).toBeFocused();expect(f.body(id)).toContain('REMOTE');await editor.dispatchEvent('compositionend',{data:'確定'});await expect(editor).toContainText('REMOTE alpha beta');await expect(editor).toBeFocused();await expect(page.getByLabel('Pageの取得状態')).toContainText('本文へ反映しました');expect(f.networkReads).toBe(1);
});
test('NATIVE-PAGE-READ-UI: unknown read stays explicit; native store recheck is networkless and never duplicates text',async({page})=>{
 const {f,editor}=await readFixture(page);f.remotePrefix('REMOTE ');f.readResult('read_unknown');await page.getByRole('button',{name:'このPageの変更を取得',exact:true}).click();await expect(page.getByLabel('Pageの取得状態')).toContainText('取得結果は未確認');await expect(editor).not.toContainText('REMOTE');expect(f.networkReads).toBe(1);f.readResult('store_pending');await page.getByRole('button',{name:'このPageの変更を取得',exact:true}).click();await expect(page.getByLabel('Pageの取得状態')).toContainText('端末保存は未確認');await expect(editor).not.toContainText('REMOTE');expect(f.networkReads).toBe(2);await page.getByRole('button',{name:'取得内容の保存を再確認',exact:true}).click();await expect(editor).toContainText('REMOTE alpha beta');expect(f.networkReads).toBe(2);expect((await diagnostic(page)).json).toMatchObject({type:'doc',content:[{type:'paragraph',content:[{type:'text',text:'REMOTE alpha beta'}]}]});for(const call of f.calls.filter(c=>c.command==='native_page_read'))expect(call.args).toEqual({handle:'native-handle',pageId:id});
});
test('NATIVE-PAGE-READ-UI: logout during held read cannot restore old content or verified screen',async({page})=>{
 const {f,editor}=await readFixture(page);f.remotePrefix('REMOTE ');f.holdRead();await page.getByRole('button',{name:'このPageの変更を取得',exact:true}).click();await f.waitReading();await page.getByRole('button',{name:'ログアウト',exact:true}).click();await expect(state(page)).toHaveText('ログインしていません');f.releaseRead();await expect(editor).toHaveCount(0);await expect(page.getByLabel('Pageの取得状態')).toHaveCount(0);expect(f.networkReads).toBe(1);
});

test('NATIVE-CATALOG-UI: explicit query, failed continuation and receive/store unknown remain distinct before remote opens',async({page},testInfo)=>{
 const f=await fixture(page);const key=f.seedCatalog();await page.goto('/native-auth.fixture.html');await login(page);await openLocal(page);const catalog=page.getByRole('region',{name:'サーバーPage一覧',exact:true});await expect(catalog).toContainText('まだ取得していません');expect(f.calls.some(c=>c.command==='native_page_catalog')).toBe(false);
 await catalog.getByRole('button',{name:'サーバーの一覧を取得',exact:true}).click();await expect(catalog).toContainText('取得した範囲：1件');expect(f.networkReads).toBe(0);f.catalogFail();await catalog.getByRole('button',{name:'一覧の続きを取得',exact:true}).click();await expect(catalog.getByRole('alert')).toContainText('表示済み');await expect(catalog.getByRole('button',{name:'一覧の続きを取得',exact:true})).toBeEnabled();f.catalogFail(false);
 const remote=catalog.getByRole('button',{name:'取得して開く：一覧の検証Page',exact:true});f.readResult('read_unknown');await remote.click();await expect(page.getByRole('alert').filter({hasText:'本文の取得結果'})).toBeVisible();await expect(page.getByRole('textbox',{name:'Page本文',exact:true})).toHaveCount(0);f.readResult('store_pending');await remote.click();await expect(page.getByRole('alert').filter({hasText:'保存は未確認'})).toBeVisible();await expect(page.getByRole('textbox',{name:'Page本文',exact:true})).toHaveCount(0);await remote.focus();await page.keyboard.press('Enter');await expect(page.getByRole('textbox',{name:'Page本文',exact:true})).toContainText('catalog remote body');expect(f.networkReads).toBe(2);expect(f.body(key)).toContain('catalog remote body');expect(f.calls.some(c=>(c.args?.request as {command?:string}|undefined)?.command==='page_create')).toBe(false);
 await expect(page.getByRole('region',{name:'端末Page一覧',exact:true}).getByRole('button',{name:'一覧の検証Page',exact:true})).toBeVisible();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:testInfo.outputPath('native-catalog.png'),fullPage:true});
});
test('NATIVE-CATALOG-UI: composition blocks query and late result after logout stays hidden',async({page})=>{
 const f=await fixture(page);f.seedCatalog();await page.goto('/native-auth.fixture.html');await login(page);await openLocal(page);const input=page.getByRole('textbox',{name:'新しいPageのタイトル',exact:true}),query=page.getByRole('button',{name:'サーバーの一覧を取得',exact:true});await input.focus();await input.dispatchEvent('compositionstart',{data:'検証'});await expect(query).toBeDisabled();await expect(input).toBeFocused();await input.dispatchEvent('compositionend',{data:'検証'});f.holdCatalog();await query.click();await f.waitCatalog();await page.getByRole('button',{name:'ログアウト',exact:true}).click();await expect(state(page)).toHaveText('ログインしていません');f.releaseCatalog();await expect(page.getByRole('region',{name:'サーバーPage一覧',exact:true})).toHaveCount(0);
});
test('NATIVE-RECONNECT-UI: explicit reconnect keeps body and pending, refreshes loaded catalog from start and permits local editing',async({page},testInfo)=>{
 const f=await fixture(page,true);f.seedCatalog();await page.goto('/native-auth.fixture.html');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();const editor=page.getByRole('textbox',{name:'Page本文',exact:true});await editor.fill('reconnect retained input');await expect.poll(()=>f.body(id)).toContain('reconnect retained input');await expect(page.getByLabel('本文の保存状態')).toContainText('端末に保存しました');await page.getByRole('button',{name:'サーバーの一覧を取得',exact:true}).click();await expect(page.getByRole('region',{name:'サーバーPage一覧',exact:true})).toContainText('取得した範囲：1件');await page.getByRole('button',{name:'一覧の続きを取得',exact:true}).click();await expect(page.getByRole('button',{name:'一覧の続きを取得',exact:true})).toHaveCount(0);
 await page.getByLabel('新しいPageのタイトル',{exact:true}).fill('未作成のタイトル');const before=f.calls.length;const reconnect=page.getByRole('button',{name:'workspaceへ再接続',exact:true});await reconnect.focus();await page.keyboard.press('Enter');await expect(page.getByRole('status').filter({hasText:'接続を更新し、端末のPageを開き直しました。'})).toBeVisible();await expect(editor).toContainText('reconnect retained input');await expect(reconnect).toBeFocused();await expect(page.getByLabel('新しいPageのタイトル',{exact:true})).toHaveValue('未作成のタイトル');expect(f.networkReads).toBe(0);expect(f.networkSends).toBe(0);const calls=f.calls.slice(before);expect(calls.filter(c=>c.command==='native_auth_restore')).toHaveLength(1);expect(calls.filter(c=>c.command==='native_page_catalog').map(c=>c.args)).toEqual([{handle:'native-handle-2',more:false}]);expect(calls.some(c=>(c.args?.request as {command?:string})?.command==='page_append')).toBe(false);await expect(page.getByRole('button',{name:'一覧の続きを取得',exact:true})).toBeVisible();await editor.click();await page.keyboard.press('End');await page.keyboard.type(' after reconnect');await expect.poll(()=>f.body(id)).toContain('reconnect retained input after reconnect');await expect(editor).toBeFocused();await page.screenshot({path:testInfo.outputPath('native-reconnect.png'),fullPage:true});
});
test('NATIVE-RECONNECT-UI: composition blocks reconnect and logout defeats held refresh without reopening Page',async({page})=>{
 const f=await fixture(page,true);await page.goto('/native-auth.fixture.html');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();const editor=page.getByRole('textbox',{name:'Page本文',exact:true}),reconnect=page.getByRole('button',{name:'workspaceへ再接続',exact:true});await editor.focus();await editor.dispatchEvent('compositionstart',{data:'変換'});await expect(reconnect).toBeDisabled();await expect(editor).toBeFocused();await editor.dispatchEvent('compositionend',{data:'変換'});f.holdRestore();await reconnect.click();await f.waitRestore();await expect(state(page)).toHaveText('workspaceへ再接続中…');await expect(reconnect).toBeFocused();await expect(reconnect).toBeDisabled();await page.keyboard.press('Enter');expect(f.calls.filter(c=>c.command==='native_auth_restore')).toHaveLength(2);await page.getByRole('button',{name:'ログアウト',exact:true}).click();await expect(state(page)).toHaveText('ログインしていません');const count=f.calls.length;f.releaseRestore();await expect(editor).toHaveCount(0);await expect(page.getByRole('region',{name:'サーバーPage一覧',exact:true})).toHaveCount(0);expect(f.calls).toHaveLength(count);
});
test('NATIVE-RECONNECT-UI: refresh failure asks login without sending, creating or automatically retrying',async({page})=>{
 const f=await fixture(page,true);await page.goto('/native-auth.fixture.html');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();f.restoreFail();const before=f.calls.length;await page.getByRole('button',{name:'workspaceへ再接続',exact:true}).click();await expect(state(page)).toHaveText('ログインしていません');await expect(page.getByRole('alert')).toContainText('再接続を確認できません');expect(f.calls.slice(before).filter(c=>c.command==='native_auth_restore')).toHaveLength(1);expect(f.networkReads).toBe(0);expect(f.networkSends).toBe(0);await login(page);await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();await expect(page.getByRole('textbox',{name:'Page本文',exact:true})).toBeVisible();
});
test('NATIVE-OFFLINE-UI: explicit status identifies missing deployment pins without offering offline editing',async({page})=>{
 const f=await fixture(page,true);await page.goto('/native-auth.fixture.html');await openLocal(page);const section=page.getByRole('region',{name:'offline許可の準備',exact:true});expect(f.calls.some(c=>c.command.startsWith('native_offline'))).toBe(false);await section.getByRole('button',{name:'offline許可を確認',exact:true}).click();await expect(page.getByLabel('offline許可の状態')).toContainText('署名設定がない');await expect(section.getByRole('button',{name:'offline許可を準備',exact:true})).toHaveCount(0);await expect(section).toContainText('許可が有効な間');
});
test('NATIVE-OFFLINE-UI: unknown prepare is rechecked locally, with no token in IPC and composition blocking controls',async({page},testInfo)=>{
 const f=await fixture(page,true);f.offlineEnabled();await page.goto('/native-auth.fixture.html');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();await page.getByRole('button',{name:'offline許可を確認',exact:true}).click();const editor=page.getByRole('textbox',{name:'Page本文',exact:true}),prepare=page.getByRole('button',{name:'offline許可を準備',exact:true});await editor.focus();await editor.dispatchEvent('compositionstart',{data:'変換'});await expect(prepare).toBeDisabled();await expect(editor).toBeFocused();await editor.dispatchEvent('compositionend',{data:'変換'});f.offlineUnknown();await prepare.click();await expect(page.getByLabel('offline許可の状態')).toContainText('未確認');await page.getByRole('button',{name:'準備結果を再確認',exact:true}).click();await expect(page.getByLabel('offline許可の状態')).toContainText('前回確認した許可の期限');expect(f.calls.filter(c=>c.command==='native_offline_prepare')).toHaveLength(1);for(const call of f.calls.filter(c=>c.command.startsWith('native_offline')))expect(call.args).toEqual({handle:'native-handle'});expect(f.networkReads).toBe(0);expect(f.networkSends).toBe(0);await page.screenshot({path:testInfo.outputPath('offline-preparation.png'),fullPage:true});
});
test('NATIVE-OFFLINE-UI: local input continues during prepare and logout withholds late lease status',async({page})=>{
 const f=await fixture(page,true);f.offlineEnabled();await page.goto('/native-auth.fixture.html');await openLocal(page);await page.getByRole('button',{name:'端末の検証Page',exact:true}).click();await page.getByRole('button',{name:'offline許可を確認',exact:true}).click();f.holdOffline();await page.getByRole('button',{name:'offline許可を準備',exact:true}).click();await f.waitOffline();const editor=page.getByRole('textbox',{name:'Page本文',exact:true});await editor.fill('local input while preparing');await expect.poll(()=>f.body(id)).toContain('local input while preparing');await expect(page.getByLabel('本文の保存状態')).toContainText('端末に保存しました');await page.getByRole('button',{name:'ログアウト',exact:true}).click();await expect(state(page)).toHaveText('ログインしていません');f.releaseOffline();await expect(page.getByLabel('offline許可の状態')).toHaveCount(0);await expect(editor).toHaveCount(0);
});

test('NATIVE-STRUCTURED-UI: task creation, editing, deletion and relation linking in native workspace',async({page},testInfo)=>{
 const f=await fixture(page,true);await page.goto('/native-auth.fixture.html');await openLocal(page);
 const structuredRegion=page.getByRole('region',{name:'TaskとRelation',exact:true});
 await expect(structuredRegion).toBeVisible();
 const taskForm=page.getByRole('form',{name:'Task編集',exact:true});
 await taskForm.getByLabel('Taskタイトル',{exact:true}).fill('E2E Native Task');
 await taskForm.getByRole('combobox',{name:'Task状態',exact:true}).selectOption('in_progress');
 await taskForm.getByRole('button',{name:'Taskを端末に保存',exact:true}).click();
 await expect(structuredRegion.getByRole('list').first()).toContainText('E2E Native Task');
 await expect(structuredRegion.getByRole('list').first()).toContainText('進行中');
 await structuredRegion.getByRole('button',{name:'TaskとRelationを同期',exact:true}).click();
 await expect(structuredRegion.getByLabel('TaskとRelationの同期状態')).toHaveText('取得した更新まで同期済み');
 expect(f.structuredSends).toBeGreaterThan(0);
 await structuredRegion.getByRole('button',{name:'Taskを編集: E2E Native Task',exact:true}).click();
 await taskForm.getByRole('combobox',{name:'Task状態',exact:true}).selectOption('done');
 await taskForm.getByRole('button',{name:'Taskの変更を保存',exact:true}).click();
 await expect(structuredRegion.getByRole('list').first()).toContainText('完了');
 const relForm=page.getByRole('form',{name:'Relation編集',exact:true});
 await relForm.getByRole('combobox',{name:'Relationの元',exact:true}).selectOption(`page:${id}`);
 const createdTask=[...f.structuredTasks.values()].find(t=>t.title==='E2E Native Task')!;
 await relForm.getByRole('combobox',{name:'Relationの先',exact:true}).selectOption(`task:${createdTask.id}`);
 await relForm.getByRole('button',{name:'Relationを端末に保存',exact:true}).click();
 await expect(structuredRegion.getByText('Page: 端末の検証Page → Task: E2E Native Task')).toBeVisible();
 await structuredRegion.getByRole('button',{name:'Taskを削除: E2E Native Task',exact:true}).click();
 await expect(structuredRegion.getByText('Taskはありません。')).toBeVisible();
 expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 await page.screenshot({path:testInfo.outputPath('native-structured.png'),fullPage:true});
});
test('NATIVE-STRUCTURED-UI: composition and active draft block logout and closing',async({page})=>{
 const f=await fixture(page,true);await page.goto('/native-auth.fixture.html');await openLocal(page);
 const structuredRegion=page.getByRole('region',{name:'TaskとRelation',exact:true});
 const taskTitle=structuredRegion.getByRole('textbox',{name:'Taskタイトル',exact:true});
 await taskTitle.fill('Draft in progress');
 await expect(page.getByText('入力中の内容があります。保存または入力を取り消してから接続を切り替えてください。')).toBeVisible();
 await expect(page.getByRole('button',{name:'workspaceを閉じる',exact:true})).toBeDisabled();
 await expect(page.getByRole('button',{name:'ログアウト',exact:true})).toBeDisabled();
 await structuredRegion.getByRole('button',{name:'Task入力を取り消す',exact:true}).click();
 await expect(page.getByText('入力中の内容があります。保存または入力を取り消してから接続を切り替えてください。')).toHaveCount(0);
 await expect(page.getByRole('button',{name:'workspaceを閉じる',exact:true})).toBeEnabled();
 await expect(page.getByRole('button',{name:'ログアウト',exact:true})).toBeEnabled();
});
